import{_ as t,o as r,c as o,a6 as a}from"./chunks/framework.DMOj2-2K.js";const p=JSON.parse('{"title":"Status & roadmap","description":"","frontmatter":{},"headers":[],"relativePath":"reference/roadmap.md","filePath":"reference/roadmap.md"}'),s={name:"reference/roadmap.md"};function d(n,e,i,l,c,u){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="status-roadmap" tabindex="-1">Status &amp; roadmap <a class="header-anchor" href="#status-roadmap" aria-label="Permalink to &quot;Status &amp; roadmap&quot;">​</a></h1><p>Cluub 0.1 is a <strong>working prototype</strong>. Here is exactly what exists today and what comes next.</p><h2 id="working-today" tabindex="-1">Working today <a class="header-anchor" href="#working-today" aria-label="Permalink to &quot;Working today&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Status</th></tr></thead><tbody><tr><td>Lexer, parser, checker, code generator, runtime and CLI (zero dependencies, ~3,300 lines)</td><td>✅</td></tr><tr><td>Models with validation, stores (memory + JSON file), clients</td><td>✅</td></tr><tr><td>Services, typed and validated APIs, dependency injection</td><td>✅</td></tr><tr><td>Pages, components, layouts, reactive state, routing, toasts</td><td>✅</td></tr><tr><td>Enforced folder structure, layer rules, naming rules</td><td>✅</td></tr><tr><td><code>ask ai</code>, <code>as Model</code>, <code>as one of</code>; Claude, OpenAI, Gemini, Ollama</td><td>✅ (verified offline with the fake AI; live provider calls not yet tested end to end)</td></tr><tr><td>Generated tests for models, services, apis, pages and buttons</td><td>✅</td></tr><tr><td>Headless full-stack UI tests</td><td>✅</td></tr><tr><td><code>cluub explain</code> for PO / BA / QA / dev</td><td>✅</td></tr><tr><td><code>cluub make</code> (AI writes code, compiler-checked repair loop)</td><td>✅ (built; needs an AI key to run)</td></tr><tr><td>CLI: new, dev (live reload), check, test, build, start, errors</td><td>✅</td></tr><tr><td>Docs with playground</td><td>✅</td></tr></tbody></table><h2 id="known-limits" tabindex="-1">Known limits <a class="header-anchor" href="#known-limits" aria-label="Permalink to &quot;Known limits&quot;">​</a></h2><ul><li><strong>Type checking is partial.</strong> Names, dependencies, fields in model construction, call arguments and layers are checked at compile time; values are checked at runtime boundaries (models, apis). Full type inference is next.</li><li><strong>Runtime errors point to generated JavaScript</strong>, not to the <code>.clb</code> line. Source maps are planned.</li><li>Stores are memory or JSON files: fine for prototypes and small apps, not for high write volume.</li><li>Components are stateless by design; page state covers most needs.</li><li>No auth, sessions, file uploads or websockets yet.</li></ul><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ol><li><strong>Language server + VS Code extension</strong>: inline errors, the same suggestions as <code>cluub check</code>, completion and hover docs (the grammar in <code>editors/</code> is the first piece).</li><li><strong>Full static types</strong> with inference, so wrong field access is caught before running.</li><li><strong>Database stores</strong>: <code>store Orders holds Order in postgres</code> / <code>sqlite</code>, with migrations generated from models.</li><li><strong>Auth</strong>: <code>page Admin at &quot;/admin&quot; for role &quot;admin&quot;</code>, plus sessions and OAuth.</li><li><strong>AI tools and agents</strong>: <code>ai agent Support uses OrderService</code>, giving the AI safe, typed access to service actions, plus streaming replies in the UI.</li><li><strong>Native compiler in Rust</strong> (same language, much faster for very large projects) and a single-binary install.</li><li><strong>Formatter</strong> (<code>cluub fmt</code>) that also normalizes dictated code.</li><li><strong>Deploy targets</strong>: static frontend + serverless backend, Docker, edge.</li></ol>',8)])])}const g=t(s,[["render",d]]);export{p as __pageData,g as default};
